    (v_route, 'Katedrála svatého Mikuláše', 'Farní kostel ve Feldkirchu. Památka v Rakousku — kus historie přímo u trasy.', 47.2381, 9.59817, 'http://commons.wikimedia.org/wiki/Special:FilePath/Dom%20St.%20Nikolaus%20am%20Domplatz%202%2C%20Feldkirch.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Dom%20St.%20Nikolaus%20am%20Domplatz%202%2C%20Feldkirch.JPG"}'::text[], 0, '{"en": {"name": "Saint Nicholas church Feldkirch", "description": "Parish church in Feldkirch, Austria. A heritage sight in Austria — a piece of history right on your route."}, "de": {"name": "Dom St. Nikolaus", "description": "Kirchengebäude in Feldkirch. Ein Denkmal in Österreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Mikołaja w Feldkirch", "description": "Świątynia katolicka. Zabytek w Austrii — kawałek historii tuż przy trasie."}, "nl": {"name": "Dom van Feldkirch", "description": "Dom van Feldkirch. Een monument in Oostenrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Nicolás", "description": "En Feldkirch. Un monumento en Austria: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Nicolas", "description": "Cathédrale à Feldkirch, Autriche. Un monument en Autriche — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrála svatého Mikuláše", "description": "Пам''ятка в Австрії — шматочок історії просто на маршруті."}}'::jsonb),
